import Indicator from "./Indicator.svelte";
import Provider from "./Provider.svelte";
import { parts } from "./parts.ts";
import Root from "./Root.svelte";
import Thumb from "./Thumb.svelte";
import Track from "./Track.svelte";
import Value from "./Value.svelte";

export const Knob = {
  Control: parts.Control,
  Indicator,
  Label: parts.Label,
  Mark: parts.Mark,
  Provider,
  Root,
  Thumb,
  Track,
  Value,
};

import type { KnobPrimitiveOptions } from "@audio-ui/primitives/knob";
import { knob } from "@audio-ui/primitives/knob";
import { createParts } from "@ui-sdk/svelte/primitive";

/** Which element each part is. */
export const parts = createParts(knob, {
  control: "div",
  indicator: "svg",
  input: "input",
  label: "div",
  mark: "div",
  root: "div",
  thumb: "div",
  track: "svg",
  value: "output",
});

/** What a provider gives every knob below it. UI SDK has no such thing. */
export type Defaults = Pick<KnobPrimitiveOptions, "dragMode">;
export const DEFAULTS = Symbol("knob defaults");
